(function(){
 var page=document.querySelector('.dtt-join-page');if(!page)return;
 var dialog=document.getElementById('dtt-join-fallback');
 var label=document.getElementById('dtt-join-selected');
 var copy=document.getElementById('dtt-join-copy');
 var close=document.getElementById('dtt-join-close');
 var current='';
 page.querySelectorAll('.dtt-jg-btn').forEach(function(button){button.addEventListener('click',function(){
   current=button.dataset.safari+' — '+button.dataset.price+' per person';
   window.dttSelectedJoiningSafari=current;
   if(typeof window.openBookingPopup==='function'){window.openBookingPopup();return;}
   label.textContent=current;
   if(dialog&&typeof dialog.showModal==='function')dialog.showModal();
   else window.prompt('Copy your enquiry:', 'Hello Deep Tanzania Tours, I would like to join '+current+'. Please share the departure dates and booking details.');
 });});
 if(copy)copy.addEventListener('click',function(){
  var line='Hello Deep Tanzania Tours, I would like to enquire about '+current+'. Please send available departure dates and booking details.';
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(line).then(function(){copy.textContent='Copied!';},function(){window.prompt('Copy enquiry:',line);});} else window.prompt('Copy enquiry:',line);
 });
 if(close)close.addEventListener('click',function(){dialog.close();copy.textContent='Copy enquiry';});
 function fixOverlap(){
  if(window.scrollY>15)return;
  page.style.paddingTop='0px';
  var pt=page.getBoundingClientRect().top,bottom=0;
  document.querySelectorAll('body > header,body > nav,#header,#main-header,.site-header,.main-header,.header-container,.header-wrapper,.header-area,.navbar').forEach(function(el){
    if(page.contains(el))return;
    var r=el.getBoundingClientRect();
    if(r.width<100||r.height<15||r.height>350||r.top>140||r.bottom<=0||r.bottom>400)return;
    bottom=Math.max(bottom,r.bottom);
  });
  if(bottom>pt+3)page.style.paddingTop=Math.ceil(bottom-pt+12)+'px';
 }
 fixOverlap();window.addEventListener('load',fixOverlap,{once:true});window.addEventListener('resize',fixOverlap,{passive:true});
})();</script><?php include __DIR__ . "/plugins/call-to-action.php"; ?><?php include __DIR__ . "/plugins/pop-up-expert.php"; ?><?php include __DIR__ . "/plugins/footer.php"; ?><?php include __DIR__ . "/plugins/booking-form.php"; ?><?php include __DIR__ . "/plugins/mobile-footer.php"; ?></body></html>